// deno-fmt-ignore-file
// Generated by `id-effect rpc gen ts` (crate id_effect_tool). Do not edit: rerun the generator.
//
// The runtime of the generated id_effect_rpc clients: plain TypeScript on web platform APIs
// (fetch, WebSocket, WebTransport, AbortSignal, TextEncoder, crypto.getRandomValues), no
// dependencies. Wire format: .maestro/specs/releases/0.12/r12-rpc-design.md (id_effect 0.12).
//
// - Queries and mutations go over `POST {url}`; the calls made in one microtask go out as one
//   batch (at most 50 calls and 1 MiB per request), every request carries `x-rpc: 1`, every
//   request with a mutation an `Idempotency-Key` of 128 random bits, and a batch with more
//   than one mutation `x-rpc-ordered: true` (the mutations run in call order).
// - Streams and subscriptions go over one multiplexed frame connection: WebTransport when
//   configured and available, else WebSocket (`{url}/ws`, subprotocol `idrpc.json.v1`), else
//   server-sent events (`GET {url}/{tag}`, server streams and subscriptions only).
// - A dropped connection reconnects with exponential backoff and jitter; server streams and
//   two-way streams resume from their last cursor (`resume` frame), subscriptions reopen after
//   their last event cursor; the cursor is the last item the caller read, so items received
//   but unread come again. Every server frame is validated before it is acted on.

/** The JSON frame codec's WebSocket subprotocol. */
export const JSON_SUBPROTOCOL = "idrpc.json.v1";
/** The most bytes of one frame (design note §5). */
export const MAX_FRAME_BYTES = 65536;
/** The most calls of one batch request (the server's default). */
export const MAX_BATCH_CALLS = 50;
/** The most body bytes of one batch request (the server's default). */
export const MAX_BATCH_BYTES = 1048576;

const MAX_CALL_ID = 2 ** 53 - 1;
const MAX_CREDITS = 1 << 20;
const MAX_CURSOR_LENGTH = 64;
const DEFAULT_MAX_RESPONSE_BYTES = 16 * 1024 * 1024;
const HELLO_TIMEOUT_MS = 10000;
const CURSOR = /^c1\.[A-Za-z0-9_-]{1,61}$/;
const SESSION = /^[A-Za-z0-9_-]{22}$/;
const TAG = /^[A-Za-z0-9_.-]{1,128}$/;
/** `Cursor::sequence(0)`: the resume point of a call that has seen no item. */
const SEQUENCE_ZERO = "c1.AgAAAAAAAAAA";

// ---------------------------------------------------------------------------------------------
// Results and errors
// ---------------------------------------------------------------------------------------------

/** How a call ended: its output, or a failure (a typed error or a reserved failure). */
export type RpcExit<A, E> =
  | { readonly _tag: "Success"; readonly value: A }
  | { readonly _tag: "Failure"; readonly error: E };

/** One Schema issue of an `InvalidInput` failure. */
export type InputIssue = { readonly path: string; readonly message: string };

/** The failures any procedure may answer without declaring them (design note §4). */
export type RpcReservedFailure =
  | { readonly _tag: "InternalError"; readonly id: string }
  | { readonly _tag: "InvalidInput"; readonly issues: readonly InputIssue[] }
  | { readonly _tag: "DeadlineExceeded" }
  | { readonly _tag: "Cancelled" }
  | { readonly _tag: "ResourceExhausted"; readonly limit: string }
  | { readonly _tag: "ResumeExpired" }
  | { readonly _tag: "Rejected"; readonly status: number; readonly title: string; readonly tag?: string };

/** The exit of a procedure whose typed error union is `E`. */
export type RpcResult<A, E> = RpcExit<A, E | RpcReservedFailure>;

/** An RFC 9457 Problem body. */
export type Problem = {
  readonly type?: string;
  readonly title?: string;
  readonly status?: number;
  readonly detail?: string;
  readonly [member: string]: unknown;
};

/** The server refused the request before any procedure ran (401, 403, 409, 413, 429, …): for a
 * batch, the whole batch. */
export class RpcProblemError extends Error {
  readonly status: number;
  readonly problem: Problem;
  constructor(status: number, problem: Problem) {
    super(`RPC request refused: ${status} ${problem.title ?? ""}`.trimEnd());
    this.name = "RpcProblemError";
    this.status = status;
    this.problem = problem;
  }
}

/** The network failed, no transport could carry the call, or the server broke the protocol. */
export class RpcTransportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RpcTransportError";
  }
}

/** Thrown by a stream's iterator when the stream ends with a failure (its `exit` resolves). */
export class RpcFailureError<E> extends Error {
  readonly error: E;
  constructor(error: E) {
    super(`RPC stream failed: ${tagOf(error)}`);
    this.name = "RpcFailureError";
    this.error = error;
  }
}

function tagOf(error: unknown): string {
  return isObject(error) && typeof error._tag === "string" ? error._tag : "unknown";
}

// ---------------------------------------------------------------------------------------------
// Options
// ---------------------------------------------------------------------------------------------

/** Options of one call. */
export interface CallOptions {
  /** Aborting it rejects the call with the signal's reason and cancels it on the server. */
  readonly signal?: AbortSignal;
  /** The deadline the server should give the call (it clamps it to its own maximum). */
  readonly deadlineMs?: number;
  /** `false` sends a query or mutation on its own instead of in the microtask's batch. */
  readonly batch?: boolean;
  /** The mutation's `Idempotency-Key` (at least 16 characters; default: 128 random bits).
   * Reusing the key of a completed call replays its result. Sent on its own. */
  readonly idempotencyKey?: string;
}

/** Options of a subscription. */
export interface SubscribeOptions extends CallOptions {
  /** Start after this event cursor (a previous stream's `cursor`). */
  readonly cursor?: string;
}

/** A transport the frame connection can use. */
export type TransportName = "webtransport" | "websocket" | "sse";

/** The part of a WebSocket the client uses (the global `WebSocket` satisfies it). */
export interface WebSocketLike {
  readonly protocol: string;
  readonly readyState: number;
  send(data: string): void;
  close(code?: number, reason?: string): void;
  addEventListener(type: "open" | "message" | "close" | "error", listener: (event: unknown) => void): void;
}

/** Opens a WebSocket (default: `new WebSocket(url, protocols)`). */
export type WebSocketFactory = (url: string, protocols: string[]) => WebSocketLike;

/** The part of `fetch` the client uses. */
export type FetchLike = (input: string, init: RequestInit) => Promise<Response>;

/** Extra request headers (an `Authorization`, for example), or a function giving them. */
export type HeadersProvider =
  | Readonly<Record<string, string>>
  | (() => Readonly<Record<string, string>> | Promise<Readonly<Record<string, string>>>);

/** WebTransport settings; WebTransport is only tried when `url` is set. */
export interface WebTransportOptions {
  /** The session URL (`https://…`). */
  readonly url: string;
  /** Pinned certificate hashes (development certificates, at most 14 days valid). */
  readonly serverCertificateHashes?: readonly { readonly algorithm: string; readonly value: BufferSource }[];
}

/** Reconnection with exponential backoff and jitter. */
export interface ReconnectOptions {
  /** The first delay (default 250 ms). */
  readonly initialDelayMs?: number;
  /** The longest delay (default 10 s). */
  readonly maxDelayMs?: number;
  /** Attempts before the open calls fail (default 10). */
  readonly maxAttempts?: number;
}

/** How a client reaches the server. */
export interface RpcClientOptions {
  /** The RPC endpoint (`https://api.example.com/rpc`). */
  readonly url: string;
  readonly headers?: HeadersProvider;
  readonly fetch?: FetchLike;
  readonly webSocket?: WebSocketFactory;
  readonly webTransport?: WebTransportOptions;
  /** The transports streams may use, in order of preference (default: all three). */
  readonly transports?: readonly TransportName[];
  readonly reconnect?: ReconnectOptions;
  /** `fetch` credentials mode (default `same-origin`). */
  readonly credentials?: RequestCredentials;
  /** The most calls in one batch request (default and maximum 50). */
  readonly maxBatchCalls?: number;
  /** The most body bytes of one batch request (default and maximum 1 MiB). */
  readonly maxBatchBytes?: number;
  /** The most bytes read of one response (default 16 MiB). */
  readonly maxResponseBytes?: number;
  /** A number in [0, 1) for the backoff jitter (default `Math.random`). */
  readonly random?: () => number;
}

// ---------------------------------------------------------------------------------------------
// Streams
// ---------------------------------------------------------------------------------------------

/** A stream of a call's outputs. Iterate it once; the iteration ends when the stream does and
 * throws `RpcFailureError` when it fails. Breaking out of the loop cancels the call. */
export interface RpcStream<O, E> extends AsyncIterable<O> {
  /** How the stream ended (rejects on a transport error or an abort). */
  readonly exit: Promise<RpcResult<null, E>>;
  /** The cursor of the last item the caller has taken from the iterator, never of an item
   * received but not yet read (subscriptions: pass it as `cursor` to resume; nothing after it
   * is skipped). */
  readonly cursor: string | undefined;
  /** Cancel the call. */
  cancel(): void;
}

/** A two-way stream: `send` items (it waits for credits), `end` the input, iterate the outputs. */
export interface RpcDuplex<I, O, E> extends RpcStream<O, E> {
  send(item: I): Promise<void>;
  end(): void;
}

type Settled = { exit: RpcExit<unknown, unknown> } | { error: unknown };

/** One received item: its connection epoch and its cursor, if it carried one. */
interface QueuedItem {
  readonly value: unknown;
  readonly epoch: number;
  readonly cursor: string | undefined;
}

class ItemQueue {
  private items: QueuedItem[] = [];
  private waiter: (() => void) | undefined;
  private settled: Settled | undefined;
  constructor(private readonly onTake: (item: QueuedItem) => void) {}

  push(value: unknown, epoch: number, cursor?: string): void {
    if (this.settled) return;
    this.items.push({ value, epoch, cursor });
    this.wake();
  }

  /** Take every received item the caller has not read (a resume from the last item read
   * delivers them again). */
  drain(): QueuedItem[] {
    const items = this.items;
    this.items = [];
    return items;
  }

  /** Put back items `drain` took, ahead of anything received since. */
  restore(items: readonly QueuedItem[]): void {
    this.items.unshift(...items);
    if (items.length > 0) this.wake();
  }

  settle(settled: Settled): void {
    if (this.settled) return;
    this.settled = settled;
    this.wake();
  }

  get isSettled(): boolean {
    return this.settled !== undefined;
  }

  async next(): Promise<IteratorResult<unknown>> {
    for (;;) {
      const item = this.items.shift();
      if (item) {
        this.onTake(item);
        return { value: item.value, done: false };
      }
      const settled = this.settled;
      if (settled) {
        if ("error" in settled) throw settled.error;
        if (settled.exit._tag === "Failure") throw new RpcFailureError(settled.exit.error);
        return { value: undefined, done: true };
      }
      await new Promise<void>((resolve) => {
        this.waiter = resolve;
      });
    }
  }

  private wake(): void {
    const waiter = this.waiter;
    this.waiter = undefined;
    waiter?.();
  }
}

class Deferred<T> {
  readonly promise: Promise<T>;
  resolve!: (value: T) => void;
  reject!: (error: unknown) => void;
  done = false;
  constructor() {
    this.promise = new Promise<T>((resolve, reject) => {
      this.resolve = (value) => {
        if (!this.done) {
          this.done = true;
          resolve(value);
        }
      };
      this.reject = (error) => {
        if (!this.done) {
          this.done = true;
          reject(error);
        }
      };
    });
    // A caller that only iterates never sees an unhandled rejection of `exit`.
    this.promise.catch(() => {});
  }
}

class StreamHandle {
  readonly exit = new Deferred<RpcExit<unknown, unknown>>();
  readonly queue: ItemQueue;
  /** The cursor of the last item the caller took (what every resume starts after). */
  cursor: string | undefined;
  cancelCall: () => void;
  constructor(onTake: (epoch: number) => void, cancelCall: () => void) {
    this.queue = new ItemQueue((item) => {
      if (item.cursor !== undefined) this.cursor = item.cursor;
      onTake(item.epoch);
    });
    this.cancelCall = cancelCall;
  }

  finish(exit: RpcExit<unknown, unknown>): void {
    this.queue.settle({ exit });
    this.exit.resolve(exit);
  }

  fail(error: unknown): void {
    this.queue.settle({ error });
    this.exit.reject(error);
  }

}

/** A stream whose handle exists once its transport is chosen (or the call failed to start). */
interface PendingStream {
  readonly handle: Promise<StreamHandle>;
  current(): StreamHandle | undefined;
  cancel(): void;
}

function streamView<I, O, E>(pending: PendingStream, cursor: string | undefined, duplex?: { send(item: I): Promise<void>; end(): void }): RpcDuplex<I, O, E> {
  const exit = pending.handle.then((h) => h.exit.promise) as Promise<RpcResult<null, E>>;
  exit.catch(() => {});
  const iterator: AsyncIterator<O> = {
    next: async () => (await (await pending.handle).queue.next()) as IteratorResult<O>,
    return: (): Promise<IteratorResult<O>> => {
      pending.cancel();
      return Promise.resolve({ value: undefined, done: true });
    },
  };
  return {
    exit,
    get cursor() {
      return pending.current()?.cursor ?? cursor;
    },
    cancel: () => pending.cancel(),
    send: duplex ? (item: I) => duplex.send(item) : () => Promise.reject(new RpcTransportError("not a two-way stream")),
    end: duplex ? () => duplex.end() : () => {},
    [Symbol.asyncIterator]: () => iterator,
  };
}

// ---------------------------------------------------------------------------------------------
// Validation of what the server sends
// ---------------------------------------------------------------------------------------------

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Whether `value` is a `WireExit` (`Success` with a `value`, or `Failure` with a tagged error). */
export function isWireExit(value: unknown): value is RpcExit<unknown, unknown> {
  if (!isObject(value)) return false;
  if (value._tag === "Success") return "value" in value;
  return value._tag === "Failure" && isObject(value.error) && typeof value.error._tag === "string";
}

/** The frame kinds (design note §5). */
export type FrameKind =
  | "call" | "item" | "end" | "exit" | "cancel" | "credit" | "hello" | "resume" | "ping" | "pong";

/** One frame. */
export interface Frame {
  readonly id: number;
  readonly kind: FrameKind;
  readonly flags: number;
  readonly tag?: string;
  readonly v?: number;
  readonly cursor?: string;
  readonly credits?: number;
  readonly payload?: unknown;
}

/** The `hello` the server opens a connection with. */
export interface Hello {
  readonly session: string;
  readonly codec: string;
  readonly max_frame: number;
  readonly window: number;
}

const FRAME_KINDS: readonly FrameKind[] = [
  "call", "item", "end", "exit", "cancel", "credit", "hello", "resume", "ping", "pong",
];
const CONNECTION_KINDS: readonly FrameKind[] = ["hello", "resume", "ping", "pong"];
const SERVER_KINDS: readonly FrameKind[] = ["item", "end", "exit", "credit", "hello", "ping", "pong"];

/** Whether `cursor` is a well-formed cursor (`c1.` + base64url, at most 64 characters). */
export function isCursor(cursor: unknown): cursor is string {
  return typeof cursor === "string" && cursor.length <= MAX_CURSOR_LENGTH && CURSOR.test(cursor);
}

/** Whether `text` is more than `max` bytes of UTF-8 (encoding it only when it might be). */
function exceeds(text: string, max: number): boolean {
  if (text.length > max) return true;
  return text.length * 3 > max && new TextEncoder().encode(text).length > max;
}

/**
 * Decode and validate one frame the server sent, before anything acts on it: at most
 * `maxBytes`, a known kind the server may send, no reserved flag bit, id 0 exactly for the
 * connection kinds, and the members each kind needs and no members it may not carry; an `exit`
 * carries a `WireExit`, a `hello` a well-formed hello. Throws `RpcTransportError` otherwise.
 */
export function decodeServerFrame(data: unknown, maxBytes: number = MAX_FRAME_BYTES): Frame {
  const bad = (why: string): never => {
    throw new RpcTransportError(`malformed frame from the server: ${why}`);
  };
  if (typeof data !== "string") return bad("not a text message");
  if (exceeds(data, maxBytes)) return bad("larger than the frame limit");
  let raw: unknown;
  try {
    raw = JSON.parse(data);
  } catch {
    return bad("not JSON");
  }
  if (!isObject(raw)) return bad("not an object");
  const { id, kind } = raw;
  const flags = raw.flags ?? 0;
  if (typeof id !== "number" || !Number.isSafeInteger(id) || id < 0) return bad("bad `id`");
  if (typeof kind !== "string" || !FRAME_KINDS.includes(kind as FrameKind)) return bad("unknown `kind`");
  const k = kind as FrameKind;
  if (!SERVER_KINDS.includes(k)) return bad(`a client frame kind \`${k}\``);
  if (typeof flags !== "number" || !Number.isInteger(flags) || flags < 0 || flags > 255) return bad("bad `flags`");
  if ((flags & ~3) !== 0) return bad("reserved flag bits");
  if (CONNECTION_KINDS.includes(k) !== (id === 0)) return bad(`a \`${k}\` frame on call id ${id}`);
  if (raw.tag !== undefined || raw.v !== undefined) return bad("`tag` or `v` outside a call frame");
  if (k !== "credit" && raw.credits !== undefined) return bad("`credits` outside a credit frame");
  if (k !== "item" && raw.cursor !== undefined) return bad("`cursor` outside an item frame");
  if (raw.cursor !== undefined && !isCursor(raw.cursor)) return bad("malformed `cursor`");
  const hasPayload = raw.payload !== undefined;
  switch (k) {
    case "exit":
      if (!isWireExit(raw.payload)) return bad("an exit without a WireExit");
      break;
    case "hello":
      if (!isHello(raw.payload)) return bad("a malformed hello");
      break;
    case "end":
    case "ping":
    case "pong":
      if (hasPayload) return bad(`a \`${k}\` frame with a payload`);
      break;
    case "credit": {
      const credits = raw.credits;
      if (typeof credits !== "number" || !Number.isInteger(credits) || credits < 1 || credits > 0xffffffff) {
        return bad("a credit frame without credits");
      }
      break;
    }
    default:
      break;
  }
  const frame: Frame = {
    id,
    kind: k,
    flags,
    ...(raw.cursor === undefined ? {} : { cursor: raw.cursor as string }),
    ...(raw.credits === undefined ? {} : { credits: raw.credits as number }),
    ...(hasPayload ? { payload: raw.payload } : {}),
  };
  return frame;
}

function isHello(value: unknown): value is Hello {
  if (!isObject(value)) return false;
  const { session, codec, max_frame: maxFrame, window } = value;
  return (
    typeof session === "string" && SESSION.test(session) && codec === JSON_SUBPROTOCOL &&
    typeof maxFrame === "number" && Number.isInteger(maxFrame) && maxFrame >= 256 && maxFrame <= MAX_FRAME_BYTES &&
    typeof window === "number" && Number.isInteger(window) && window >= 1 && window <= 4096
  );
}

function encodeFrame(frame: Frame): string {
  return JSON.stringify(frame);
}

// ---------------------------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------------------------

/** A fresh `Idempotency-Key`: 128 random bits, base64url (22 characters). */
export function randomKey(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  let text = "";
  for (const b of bytes) text += String.fromCharCode(b);
  return btoa(text).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function abortReason(signal: AbortSignal): unknown {
  return signal.reason ?? new DOMException("The call was aborted.", "AbortError");
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** The delay before reconnect attempt `attempt` (0-based): exponential, capped, with jitter
 * (between half and all of the step). */
export function backoffDelay(attempt: number, options: ReconnectOptions = {}, random: () => number = Math.random): number {
  const initial = options.initialDelayMs ?? 250;
  const max = options.maxDelayMs ?? 10000;
  const step = Math.min(max, initial * 2 ** Math.min(attempt, 30));
  return Math.round(step / 2 + random() * (step / 2));
}

async function readCapped(response: Response, max: number): Promise<string> {
  const body = response.body;
  if (!body) return "";
  const reader = body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > max) {
      await reader.cancel();
      throw new RpcTransportError(`response larger than ${max} bytes`);
    }
    chunks.push(value);
  }
  const all = new Uint8Array(total);
  let at = 0;
  for (const chunk of chunks) {
    all.set(chunk, at);
    at += chunk.byteLength;
  }
  return new TextDecoder().decode(all);
}

function mediaType(response: Response): string {
  return (response.headers.get("content-type") ?? "").split(";")[0].trim().toLowerCase();
}

async function problemOf(response: Response, max: number): Promise<RpcProblemError> {
  let problem: Problem = { status: response.status };
  try {
    const parsed: unknown = JSON.parse(await readCapped(response, max));
    if (isObject(parsed)) problem = parsed as Problem;
  } catch {
    // The status alone.
  }
  return new RpcProblemError(response.status, problem);
}

// ---------------------------------------------------------------------------------------------
// Unary calls over HTTP, batched per microtask
// ---------------------------------------------------------------------------------------------

type UnaryKind = "query" | "mutation";

interface PendingUnary {
  readonly id: number;
  readonly tag: string;
  readonly kind: UnaryKind;
  readonly body: string;
  readonly bytes: number;
  readonly options: CallOptions;
  readonly result: Deferred<RpcExit<unknown, unknown>>;
  controller?: AbortController;
}

class HttpUnary {
  private queue: PendingUnary[] = [];
  private scheduled = false;
  private nextId = 1;
  constructor(private readonly conn: RpcConnection) {}

  call(tag: string, v: number, kind: UnaryKind, input: unknown, options: CallOptions): Promise<RpcExit<unknown, unknown>> {
    const signal = options.signal;
    if (signal?.aborted) return Promise.reject(abortReason(signal));
    if (options.idempotencyKey !== undefined && options.idempotencyKey.length < 16) {
      return Promise.reject(new RangeError("an Idempotency-Key needs at least 16 characters"));
    }
    const id = this.nextId;
    this.nextId = this.nextId >= MAX_CALL_ID ? 1 : this.nextId + 1;
    const body = JSON.stringify({ id, tag, v, payload: input ?? null });
    const pending: PendingUnary = {
      id, tag, kind, body, bytes: new TextEncoder().encode(body).length, options,
      result: new Deferred(),
    };
    signal?.addEventListener("abort", () => {
      const at = this.queue.indexOf(pending);
      if (at >= 0) this.queue.splice(at, 1);
      pending.controller?.abort(abortReason(signal));
      pending.result.reject(abortReason(signal));
    }, { once: true });
    if (options.batch === false || options.idempotencyKey !== undefined) {
      void this.send([pending]);
    } else {
      this.queue.push(pending);
      if (!this.scheduled) {
        this.scheduled = true;
        queueMicrotask(() => this.flush());
      }
    }
    return pending.result.promise;
  }

  private flush(): void {
    this.scheduled = false;
    const calls = this.queue;
    this.queue = [];
    const groups = new Map<string, PendingUnary[]>();
    for (const call of calls) {
      const key = String(call.options.deadlineMs ?? "");
      const group = groups.get(key) ?? [];
      group.push(call);
      groups.set(key, group);
    }
    const maxCalls = Math.max(1, Math.min(MAX_BATCH_CALLS, this.conn.options.maxBatchCalls ?? MAX_BATCH_CALLS));
    const maxBytes = Math.max(2, Math.min(MAX_BATCH_BYTES, this.conn.options.maxBatchBytes ?? MAX_BATCH_BYTES));
    for (const group of groups.values()) {
      let chunk: PendingUnary[] = [];
      let bytes = 2;
      for (const call of group) {
        if (chunk.length > 0 && (chunk.length >= maxCalls || bytes + call.bytes + 1 > maxBytes)) {
          void this.send(chunk);
          chunk = [];
          bytes = 2;
        }
        chunk.push(call);
        bytes += call.bytes + 1;
      }
      if (chunk.length > 0) void this.send(chunk);
    }
  }

  private async send(chunk: PendingUnary[]): Promise<void> {
    const controller = new AbortController();
    if (chunk.length === 1) chunk[0].controller = controller;
    try {
      const headers = await this.conn.headers();
      headers["content-type"] = "application/json";
      headers.accept = "application/json";
      headers["x-rpc"] = "1";
      const deadline = chunk[0].options.deadlineMs;
      if (deadline !== undefined) headers["x-rpc-deadline-ms"] = String(Math.max(0, Math.round(deadline)));
      const mutations = chunk.filter((c) => c.kind === "mutation").length;
      if (mutations > 0) headers["idempotency-key"] = chunk[0].options.idempotencyKey ?? randomKey();
      if (mutations > 1) headers["x-rpc-ordered"] = "true";
      const live = chunk.filter((c) => !c.result.done);
      if (live.length === 0) return;
      const body = chunk.length === 1 ? chunk[0].body : `[${chunk.map((c) => c.body).join(",")}]`;
      const response = await this.conn.fetch(this.conn.options.url, {
        method: "POST",
        headers,
        body,
        signal: controller.signal,
        credentials: this.conn.options.credentials ?? "same-origin",
      });
      const max = this.conn.options.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;
      const type = mediaType(response);
      // A refusal before any procedure ran: a Problem, or a guard's bare status.
      if (type === "application/problem+json" || !response.ok && type !== "application/json") {
        throw await problemOf(response, max);
      }
      if (type !== "application/json") {
        throw new RpcTransportError(`unexpected ${response.status} response (${type || "no content type"})`);
      }
      const parsed: unknown = JSON.parse(await readCapped(response, max));
      if (chunk.length === 1) {
        chunk[0].result.resolve(resultOf(parsed, chunk[0]));
      } else {
        if (!Array.isArray(parsed) || parsed.length !== chunk.length) {
          throw new RpcTransportError("a batch answered with another number of results");
        }
        chunk.forEach((call, i) => call.result.resolve(resultOf(parsed[i], call)));
      }
    } catch (error) {
      const failure = error instanceof RpcProblemError || error instanceof RpcTransportError || error instanceof RangeError
        ? error
        : error instanceof SyntaxError
          ? new RpcTransportError("the server answered malformed JSON")
          : new RpcTransportError(`the request failed: ${String(error)}`);
      for (const call of chunk) call.result.reject(failure);
    }
  }
}

function resultOf(value: unknown, call: PendingUnary): RpcExit<unknown, unknown> {
  if (!isObject(value) || value.tag !== call.tag || (value.id !== undefined && value.id !== call.id)) {
    throw new RpcTransportError(`a result that does not answer call ${call.id} (${call.tag})`);
  }
  if (!isWireExit(value.exit)) throw new RpcTransportError(`a malformed exit for ${call.tag}`);
  return value.exit;
}

// ---------------------------------------------------------------------------------------------
// Frame channels: WebSocket and WebTransport
// ---------------------------------------------------------------------------------------------

interface FrameChannel {
  readonly name: TransportName;
  send(frame: Frame, text: string): void;
  close(code?: number): void;
}

interface ChannelEvents {
  onMessage(data: unknown): void;
  onClose(): void;
}

function openWebSocket(factory: WebSocketFactory, url: string, events: ChannelEvents): Promise<FrameChannel> {
  return new Promise((resolve, reject) => {
    let opened = false;
    let socket: WebSocketLike;
    try {
      socket = factory(url, [JSON_SUBPROTOCOL]);
    } catch (error) {
      reject(new RpcTransportError(`WebSocket refused: ${String(error)}`));
      return;
    }
    socket.addEventListener("open", () => {
      if (socket.protocol !== JSON_SUBPROTOCOL) {
        socket.close(1002, "subprotocol");
        reject(new RpcTransportError(`the server chose subprotocol \`${socket.protocol}\``));
        return;
      }
      opened = true;
      resolve({
        name: "websocket",
        send: (_frame, text) => socket.send(text),
        close: (code) => socket.close(code ?? 1000),
      });
    });
    socket.addEventListener("message", (event) => {
      if (opened) events.onMessage((event as { data: unknown }).data);
    });
    socket.addEventListener("close", () => {
      if (opened) events.onClose();
      else reject(new RpcTransportError("the WebSocket closed before it opened"));
    });
    socket.addEventListener("error", () => {
      if (!opened) reject(new RpcTransportError("the WebSocket failed to open"));
    });
  });
}

interface WebTransportStream {
  readonly readable: ReadableStream<Uint8Array>;
  readonly writable: WritableStream<Uint8Array>;
}

interface WebTransportSession {
  readonly ready: Promise<unknown>;
  readonly closed: Promise<unknown>;
  createBidirectionalStream(): Promise<WebTransportStream>;
  close(info?: { closeCode?: number; reason?: string }): void;
}

type WebTransportConstructor = new (url: string, options?: Record<string, unknown>) => WebTransportSession;

function webTransportConstructor(): WebTransportConstructor | undefined {
  return (globalThis as { WebTransport?: WebTransportConstructor }).WebTransport;
}

/** Length-delimited records (u32 big-endian length, then the frame's UTF-8 bytes). */
function record(text: string): Uint8Array {
  const bytes = new TextEncoder().encode(text);
  const out = new Uint8Array(4 + bytes.length);
  new DataView(out.buffer).setUint32(0, bytes.length);
  out.set(bytes, 4);
  return out;
}

async function readRecords(readable: ReadableStream<Uint8Array>, onRecord: (text: string) => void): Promise<void> {
  const reader = readable.getReader();
  let buffer = new Uint8Array(0);
  for (;;) {
    const { value, done } = await reader.read();
    if (done) return;
    const joined = new Uint8Array(buffer.length + value.length);
    joined.set(buffer);
    joined.set(value, buffer.length);
    buffer = joined;
    while (buffer.length >= 4) {
      const length = new DataView(buffer.buffer, buffer.byteOffset).getUint32(0);
      if (length > MAX_FRAME_BYTES) throw new RpcTransportError("a record larger than the frame limit");
      if (buffer.length < 4 + length) break;
      onRecord(new TextDecoder().decode(buffer.subarray(4, 4 + length)));
      buffer = buffer.slice(4 + length);
    }
  }
}

/**
 * WebTransport: the connection frames (`hello`, `resume`, `ping`, `pong`) on the first
 * bidirectional stream the client opens, each call on a bidirectional stream of its own (design
 * note §5: one length-delimited record per frame). Frames for a call whose stream is gone (a
 * call resumed on a new session) go on the connection stream.
 */
async function openWebTransport(options: WebTransportOptions, events: ChannelEvents): Promise<FrameChannel> {
  const Ctor = webTransportConstructor();
  if (!Ctor) throw new RpcTransportError("WebTransport is not available");
  const init: Record<string, unknown> = {};
  if (options.serverCertificateHashes) init.serverCertificateHashes = options.serverCertificateHashes;
  const session = new Ctor(options.url, init);
  await session.ready;
  const control = await session.createBidirectionalStream();
  // A call's writer once its stream is open: frames sent meanwhile wait for it, in order.
  const writers = new Map<number, Promise<WritableStreamDefaultWriter<Uint8Array>>>();
  const controlWriter = control.writable.getWriter();
  // The server learns of a stream from its first record, and answers `hello` on the stream whose
  // first record is a connection frame: open the control stream with a `ping`.
  void controlWriter.write(record(JSON.stringify({ id: 0, kind: "ping", flags: 0 })));
  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    events.onClose();
  };
  const read = (readable: ReadableStream<Uint8Array>) =>
    readRecords(readable, (text) => events.onMessage(text)).catch(() => session.close({ closeCode: 1 }));
  void read(control.readable).finally(close);
  void session.closed.then(close, close);
  return {
    name: "webtransport",
    send: (frame, text) => {
      const bytes = record(text);
      if (frame.kind === "call") {
        const opened = session.createBidirectionalStream().then((stream) => {
          const writer = stream.writable.getWriter();
          void read(stream.readable).finally(() => writers.delete(frame.id));
          void writer.write(bytes).catch(() => session.close({ closeCode: 1 }));
          return writer;
        });
        writers.set(frame.id, opened);
        opened.catch(() => session.close({ closeCode: 1 }));
        return;
      }
      const writer = frame.id === 0 ? undefined : writers.get(frame.id);
      const written = writer
        ? writer.then((w) => w.write(bytes))
        : controlWriter.write(bytes);
      void written.catch(() => session.close({ closeCode: 1 }));
    },
    close: () => session.close({ closeCode: 0 }),
  };
}

// ---------------------------------------------------------------------------------------------
// The frame connection: calls multiplexed by id, credits, reconnect and resume
// ---------------------------------------------------------------------------------------------

type StreamKind = "server_stream" | "client_stream" | "bidi" | "subscription";

interface FrameCall {
  readonly id: number;
  readonly kind: StreamKind;
  readonly tag: string;
  readonly v: number;
  readonly input: unknown;
  readonly handle: StreamHandle;
  /** Items consumed since the last credit grant (of the current connection only). */
  unacked: number;
  /** Items this side may still send. */
  sendCredits: number;
  /** After a resume, a two-way call waits for a credit frame that sets its window. */
  awaitingWindow: boolean;
  sendWaiters: (() => void)[];
  opened: boolean;
}

class FrameConnection {
  private channel: FrameChannel | undefined;
  private connecting: Promise<void> | undefined;
  private readonly calls = new Map<number, FrameCall>();
  private nextId = 1;
  private session: string | undefined;
  private window = 32;
  private maxFrame = MAX_FRAME_BYTES;
  private epoch = 0;
  private closedByUser = false;
  private helloWaiter: { resolve: (hello: Hello) => void; reject: (error: unknown) => void } | undefined;
  /** The frame transport that worked, sticky for this connection. */
  transport: TransportName | undefined;

  constructor(private readonly conn: RpcConnection) {}

  private candidates(): TransportName[] {
    const wanted = this.conn.options.transports ?? ["webtransport", "websocket", "sse"];
    return wanted.filter((name) =>
      name === "webtransport"
        ? this.conn.options.webTransport !== undefined && webTransportConstructor() !== undefined
        : name === "websocket" && this.conn.webSocketFactory() !== undefined
    );
  }

  /** Whether a frame connection is up. */
  get connected(): boolean {
    return this.channel !== undefined && this.connecting === undefined;
  }

  /** A connection attempt ended: senders that waited for it check again. */
  private settled(): void {
    this.connecting = undefined;
    for (const call of this.calls.values()) this.wakeSenders(call);
  }

  /** Connect (or wait for the connection being made); rejects when no frame transport works. */
  ensure(): Promise<void> {
    if (this.connected) return Promise.resolve();
    if (!this.connecting) {
      this.closedByUser = false;
      this.connecting = this.connect(false).finally(() => {
        this.settled();
      });
    }
    return this.connecting;
  }

  private async open(name: TransportName): Promise<FrameChannel> {
    const epoch = ++this.epoch;
    const events: ChannelEvents = {
      onMessage: (data) => {
        if (this.epoch === epoch) this.receive(data);
      },
      onClose: () => {
        if (this.epoch === epoch) this.lost();
      },
    };
    if (name === "webtransport") {
      const options = this.conn.options.webTransport;
      if (!options) throw new RpcTransportError("WebTransport is not configured");
      return await openWebTransport(options, events);
    }
    const factory = this.conn.webSocketFactory();
    if (!factory) throw new RpcTransportError("WebSocket is not available");
    return await openWebSocket(factory, webSocketUrl(this.conn.options.url), events);
  }

  private async connect(resuming: boolean): Promise<void> {
    const names = this.transport ? [this.transport] : this.candidates();
    let lastError: unknown = new RpcTransportError("no frame transport (WebTransport, WebSocket) is available");
    for (const name of names) {
      // Items received but not yet read when a resume goes out: the server sends them again.
      let unread: Map<FrameCall, QueuedItem[]> | undefined;
      try {
        const hello = this.nextHello();
        this.channel = await this.open(name);
        const first = await hello;
        this.transport = name;
        this.window = first.window;
        this.maxFrame = first.max_frame;
        const resumable = [...this.calls.values()].filter((c) => c.opened && (c.kind === "server_stream" || c.kind === "bidi"));
        if (resuming && this.session !== undefined && resumable.length > 0) {
          const answer = this.nextHello();
          // Resume after the last item the caller read; what it has not read yet is dropped
          // here (and delivered again), so nothing is skipped and nothing arrives twice.
          const drained = new Map<FrameCall, QueuedItem[]>();
          for (const c of resumable) drained.set(c, c.handle.queue.drain());
          unread = drained;
          const calls = resumable.map((c) => ({ id: c.id, cursor: c.handle.cursor ?? SEQUENCE_ZERO }));
          this.write({ id: 0, kind: "resume", flags: 0, payload: { session: this.session, calls } });
          const second = await answer;
          const accepted = second.session === this.session;
          this.session = second.session;
          unread = undefined;
          for (const call of resumable) {
            if (!accepted) {
              // Refused: the caller still reads what it had received, then `ResumeExpired`.
              call.handle.queue.restore(drained.get(call) ?? []);
              this.calls.delete(call.id);
              call.handle.finish({ _tag: "Failure", error: { _tag: "ResumeExpired" } });
              this.wakeSenders(call);
              continue;
            }
            call.unacked = 0;
            if (call.kind === "bidi") {
              call.sendCredits = 0;
              call.awaitingWindow = true;
            }
          }
        } else {
          this.session = first.session;
        }
        // Subscriptions reopen after their last event cursor; calls started meanwhile open now.
        for (const call of [...this.calls.values()]) {
          if (!call.opened || call.kind === "subscription") this.openCall(call);
          else this.wakeSenders(call);
        }
        return;
      } catch (error) {
        for (const [call, items] of unread ?? []) call.handle.queue.restore(items);
        const waiter = this.helloWaiter;
        this.helloWaiter = undefined;
        waiter?.reject(error);
        const channel = this.channel;
        this.channel = undefined;
        this.epoch += 1;
        channel?.close(1000);
        lastError = error;
      }
    }
    throw lastError;
  }

  private nextHello(): Promise<Hello> {
    const hello = new Promise<Hello>((resolve, reject) => {
      const waiter = {
        resolve: (value: Hello) => {
          clearTimeout(timer);
          resolve(value);
        },
        reject: (error: unknown) => {
          clearTimeout(timer);
          reject(error);
        },
      };
      const timer = setTimeout(() => {
        if (this.helloWaiter === waiter) this.helloWaiter = undefined;
        reject(new RpcTransportError("no hello from the server"));
      }, HELLO_TIMEOUT_MS);
      this.helloWaiter = waiter;
    });
    hello.catch(() => {}); // awaited by `connect`, unless opening the channel failed first
    return hello;
  }

  /** Send `frame`; `false` when there is no connection (the frame is dropped: calls are
   * reopened or resumed on the next connection). Throws `RangeError` for a frame over the
   * server's `max_frame`. */
  private write(frame: Frame): boolean {
    const channel = this.channel;
    if (!channel) return false;
    const text = encodeFrame(frame);
    if (exceeds(text, this.maxFrame)) throw new RangeError("frame larger than the server's max_frame");
    try {
      channel.send(frame, text);
      return true;
    } catch {
      return false;
    }
  }

  /** A protocol violation: drop this connection (calls resume or fail as on any loss). */
  private violation(): void {
    this.channel?.close(1002);
    this.lost();
  }

  private receive(data: unknown): void {
    let frame: Frame;
    try {
      frame = decodeServerFrame(data, this.maxFrame);
    } catch {
      this.violation();
      return;
    }
    switch (frame.kind) {
      case "hello": {
        const waiter = this.helloWaiter;
        this.helloWaiter = undefined;
        if (waiter) waiter.resolve(frame.payload as Hello);
        else this.violation();
        return;
      }
      case "ping":
        this.write({ id: 0, kind: "pong", flags: 0 });
        return;
      case "pong":
        return;
      default:
        break;
    }
    if (this.helloWaiter) {
      this.violation(); // a call frame before the hello
      return;
    }
    const call = this.calls.get(frame.id);
    if (!call) return; // a call this side already finished (cancelled)
    switch (frame.kind) {
      case "item":
        if (call.kind === "client_stream") {
          this.violation();
          return;
        }
        call.handle.queue.push(frame.payload ?? null, this.epoch, frame.cursor);
        return;
      case "credit": {
        const credits = frame.credits ?? 0;
        call.sendCredits = call.awaitingWindow
          ? Math.min(credits, MAX_CREDITS)
          : Math.min(call.sendCredits + credits, MAX_CREDITS);
        call.awaitingWindow = false;
        this.wakeSenders(call);
        return;
      }
      case "exit":
        this.calls.delete(call.id);
        call.handle.finish(frame.payload as RpcExit<unknown, unknown>);
        this.wakeSenders(call);
        return;
      default:
        return; // `end`: the server's half-close carries nothing a client acts on
    }
  }

  private wakeSenders(call: FrameCall): void {
    for (const wake of call.sendWaiters.splice(0)) wake();
  }

  private failCall(call: FrameCall, error: unknown): void {
    this.calls.delete(call.id);
    call.handle.fail(error);
    this.wakeSenders(call);
  }

  /** The connection dropped (not by `close`). */
  private lost(): void {
    if (!this.channel) return;
    this.channel = undefined;
    this.epoch += 1;
    const waiter = this.helloWaiter;
    this.helloWaiter = undefined;
    waiter?.reject(new RpcTransportError("the connection dropped"));
    for (const call of [...this.calls.values()]) {
      if (call.kind === "client_stream" && call.opened) {
        this.failCall(call, new RpcTransportError("the connection dropped during a client stream"));
      }
    }
    if (this.closedByUser || this.calls.size === 0 || this.connecting) return;
    this.connecting = this.reconnect().finally(() => {
      this.settled();
    });
  }

  private async reconnect(): Promise<void> {
    const options = this.conn.options.reconnect ?? {};
    const attempts = options.maxAttempts ?? 10;
    for (let attempt = 0; attempt < attempts; attempt++) {
      await sleep(backoffDelay(attempt, options, this.conn.options.random));
      if (this.closedByUser || this.calls.size === 0) return;
      try {
        await this.connect(true);
        return;
      } catch {
        // Try again after the next delay.
      }
    }
    const error = new RpcTransportError(`could not reconnect after ${attempts} attempts`);
    for (const call of [...this.calls.values()]) this.failCall(call, error);
  }

  private openCall(call: FrameCall): void {
    // A subscription (re)opens after the last event the caller read; events it received but
    // has not read come again on the new call.
    if (call.kind === "subscription") call.handle.queue.drain();
    const cursor = call.kind === "subscription" ? call.handle.cursor : undefined;
    call.unacked = 0;
    call.sendCredits = this.window;
    call.awaitingWindow = false;
    const payload = call.kind === "client_stream" || call.kind === "bidi" ? null : call.input ?? null;
    try {
      call.opened = this.write({
        id: call.id,
        kind: "call",
        flags: 0,
        tag: call.tag,
        v: call.v,
        ...(cursor === undefined ? {} : { cursor }),
        payload,
      });
    } catch {
      call.handle.finish({ _tag: "Failure", error: { _tag: "ResourceExhausted", limit: "max_frame" } });
      this.calls.delete(call.id);
    }
    this.wakeSenders(call);
  }

  /** Start a call: it opens now, or as soon as the connection is up. */
  start(kind: StreamKind, tag: string, v: number, input: unknown, options: SubscribeOptions): FrameCall {
    const id = this.nextId;
    this.nextId = this.nextId >= MAX_CALL_ID ? 1 : this.nextId + 1;
    const handle = new StreamHandle((epoch) => this.consumed(id, epoch), () => this.cancel(id));
    if (options.cursor !== undefined) handle.cursor = options.cursor;
    const call: FrameCall = {
      id, kind, tag, v, input, handle,
      unacked: 0, sendCredits: 0, awaitingWindow: false, sendWaiters: [], opened: false,
    };
    const signal = options.signal;
    if (signal?.aborted) {
      handle.fail(abortReason(signal));
      return call;
    }
    this.calls.set(id, call);
    signal?.addEventListener("abort", () => {
      if (this.calls.get(id) === call) {
        this.cancel(id);
        handle.fail(abortReason(signal));
      }
    }, { once: true });
    if (this.connected) {
      this.openCall(call);
    } else {
      this.ensure().then(
        () => {
          if (this.calls.get(id) === call && !call.opened) {
            this.failCall(call, new RpcTransportError("the connection is down"));
          }
        },
        (error) => {
          if (this.calls.get(id) === call) this.failCall(call, error);
        },
      );
    }
    return call;
  }

  private consumed(id: number, epoch: number): void {
    const call = this.calls.get(id);
    if (!call || epoch !== this.epoch) return; // credited by a resume's cursor, or finished
    call.unacked += 1;
    if (call.unacked >= Math.max(1, Math.floor(this.window / 2))) {
      const credits = call.unacked;
      call.unacked = 0;
      this.write({ id, kind: "credit", flags: 0, credits });
    }
  }

  /** Cancel a call: a `cancel` frame, and the stream fails with an `AbortError`. */
  cancel(id: number): void {
    const call = this.calls.get(id);
    if (!call) return;
    if (call.opened) this.write({ id, kind: "cancel", flags: 0 });
    this.failCall(call, new DOMException("The call was cancelled.", "AbortError"));
  }

  private async sendable(call: FrameCall, needsCredit: boolean): Promise<boolean> {
    for (;;) {
      if (this.calls.get(call.id) !== call) return false;
      const credit = !needsCredit || call.sendCredits > 0 && !call.awaitingWindow;
      if (call.opened && this.connected && credit) return true;
      await new Promise<void>((resolve) => call.sendWaiters.push(resolve));
    }
  }

  /** Send one input item of `call`, waiting for a credit. */
  async sendItem(call: FrameCall, item: unknown): Promise<void> {
    if (!(await this.sendable(call, true))) throw new RpcTransportError("the call has ended");
    call.sendCredits -= 1;
    try {
      this.write({ id: call.id, kind: "item", flags: 0, payload: item ?? null });
    } catch (error) {
      this.cancel(call.id);
      throw error;
    }
  }

  /** Half-close `call`'s input. */
  async endInput(call: FrameCall): Promise<void> {
    if (await this.sendable(call, false)) this.write({ id: call.id, kind: "end", flags: 1 });
  }

  close(): void {
    this.closedByUser = true;
    const channel = this.channel;
    this.channel = undefined;
    this.epoch += 1;
    channel?.close(1000);
    const error = new RpcTransportError("the client was closed");
    for (const call of [...this.calls.values()]) this.failCall(call, error);
  }
}
function webSocketUrl(url: string): string {
  const u = new URL(url);
  u.protocol = u.protocol === "https:" ? "wss:" : u.protocol === "http:" ? "ws:" : u.protocol;
  u.pathname = `${u.pathname.replace(/\/+$/, "")}/ws`;
  return u.toString();
}

// ---------------------------------------------------------------------------------------------
// Server-sent events (server streams and subscriptions when no frame transport works)
// ---------------------------------------------------------------------------------------------

const MAX_SSE_LINE = MAX_FRAME_BYTES + 64;

function sseStream(conn: RpcConnection, kind: "server_stream" | "subscription", tag: string, v: number, input: unknown, options: SubscribeOptions): StreamHandle {
  const controller = new AbortController();
  let finished = false;
  const handle = new StreamHandle(() => {}, () => {
    finished = true;
    controller.abort();
    handle.fail(new DOMException("The call was cancelled.", "AbortError"));
  });
  if (options.cursor !== undefined) handle.cursor = options.cursor;
  const signal = options.signal;
  if (signal?.aborted) {
    handle.fail(abortReason(signal));
    return handle;
  }
  signal?.addEventListener("abort", () => {
    finished = true;
    controller.abort();
    handle.fail(abortReason(signal));
  }, { once: true });
  const url = `${conn.options.url.replace(/\/+$/, "")}/${tag}?input=${encodeURIComponent(JSON.stringify(input ?? null))}`;
  const run = async (): Promise<void> => {
    const reconnect = conn.options.reconnect ?? {};
    const attempts = reconnect.maxAttempts ?? 10;
    let attempt = 0;
    for (;;) {
      let failure: unknown;
      try {
        const headers = await conn.headers();
        headers.accept = "text/event-stream";
        headers["x-rpc"] = "1";
        headers["x-rpc-version"] = String(v);
        if (kind === "subscription") {
          // Reconnect after the last event the caller read; unread ones come again.
          handle.queue.drain();
          if (handle.cursor !== undefined) headers["last-event-id"] = handle.cursor;
        }
        const response = await conn.fetch(url, {
          method: "GET",
          headers,
          signal: controller.signal,
          credentials: conn.options.credentials ?? "same-origin",
        });
        const type = mediaType(response);
        if (type === "application/problem+json" || !response.ok) {
          throw await problemOf(response, conn.options.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES);
        }
        if (type !== "text/event-stream") throw new RpcTransportError(`unexpected ${type || "untyped"} event stream`);
        attempt = 0;
        const exit = await readEvents(response, handle);
        if (exit) {
          finished = true;
          handle.finish(exit);
          return;
        }
        failure = new RpcTransportError("the event stream ended before its exit");
      } catch (error) {
        if (finished) return;
        if (error instanceof RpcProblemError || error instanceof RpcTransportError && /malformed/.test(error.message)) {
          finished = true;
          handle.fail(error);
          return;
        }
        failure = error instanceof RpcTransportError ? error : new RpcTransportError(`the event stream failed: ${String(error)}`);
      }
      if (finished) return;
      // Server streams do not resume over SSE; subscriptions reconnect after their cursor.
      if (kind !== "subscription" || attempt >= attempts) {
        finished = true;
        handle.fail(failure);
        return;
      }
      await sleep(backoffDelay(attempt, reconnect, conn.options.random));
      attempt += 1;
      if (finished) return;
    }
  };
  void run();
  return handle;
}

/** Read `event: item` / `event: exit` events; the exit, or `undefined` when the body ended first. */
async function readEvents(response: Response, handle: StreamHandle): Promise<RpcExit<unknown, unknown> | undefined> {
  const body = response.body;
  if (!body) return undefined;
  const reader = body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  let event = "";
  let data: string[] = [];
  let id: string | undefined;
  const bad = (why: string): never => {
    void reader.cancel();
    throw new RpcTransportError(`malformed event stream: ${why}`);
  };
  const dispatch = (): RpcExit<unknown, unknown> | undefined => {
    const name = event || "message";
    const text = data.join("\n");
    const cursor = id;
    event = "";
    data = [];
    id = undefined;
    if (name === "message" && text === "") return undefined;
    let value: unknown;
    try {
      value = JSON.parse(text);
    } catch {
      return bad("data is not JSON");
    }
    if (name === "item") {
      if (cursor !== undefined && !isCursor(cursor)) return bad("malformed id");
      handle.queue.push(value, 0, cursor);
      return undefined;
    }
    if (name === "exit") {
      if (!isWireExit(value)) return bad("an exit without a WireExit");
      return value;
    }
    return bad(`unknown event \`${name}\``);
  };
  for (;;) {
    const { value, done } = await reader.read();
    if (done) return undefined;
    buffer += value;
    for (;;) {
      const at = buffer.search(/\r\n|\r|\n/);
      if (at < 0) {
        if (buffer.length > MAX_SSE_LINE) bad("line too long");
        break;
      }
      const line = buffer.slice(0, at);
      buffer = buffer.slice(buffer.startsWith("\r\n", at) ? at + 2 : at + 1);
      if (line === "") {
        const exit = dispatch();
        if (exit) {
          void reader.cancel();
          return exit;
        }
        continue;
      }
      if (line.startsWith(":")) continue;
      const colon = line.indexOf(":");
      const field = colon < 0 ? line : line.slice(0, colon);
      const rest = colon < 0 ? "" : line.slice(colon + 1).replace(/^ /, "");
      if (field === "event") event = rest;
      else if (field === "data") {
        data.push(rest);
        if (data.reduce((n, d) => n + d.length, 0) > MAX_SSE_LINE) bad("event too large");
      } else if (field === "id") id = rest;
    }
  }
}

// ---------------------------------------------------------------------------------------------
// The connection the generated clients share
// ---------------------------------------------------------------------------------------------

function cancelledError(): DOMException {
  return new DOMException("The call was cancelled.", "AbortError");
}

/** One client's connection to the server: the HTTP batcher and the frame connection that
 * every generated service client built on it shares. */
export class RpcConnection {
  readonly options: RpcClientOptions;
  private readonly unaryCalls: HttpUnary;
  private readonly frames: FrameConnection;
  /** No frame transport could connect: server streams and subscriptions use SSE. */
  private sseFallback = false;

  constructor(options: RpcClientOptions) {
    new URL(options.url); // throws on a malformed URL
    this.options = options;
    this.unaryCalls = new HttpUnary(this);
    this.frames = new FrameConnection(this);
  }

  /** The transport streams use: set once a frame connection opened, or `sse` after the fallback. */
  get transport(): TransportName | undefined {
    return this.sseFallback ? "sse" : this.frames.transport;
  }

  /** @internal */
  fetch(input: string, init: RequestInit): Promise<Response> {
    const f = this.options.fetch ?? (globalThis.fetch as FetchLike | undefined);
    if (!f) return Promise.reject(new RpcTransportError("fetch is not available"));
    return f(input, init);
  }

  /** @internal */
  webSocketFactory(): WebSocketFactory | undefined {
    if (this.options.webSocket) return this.options.webSocket;
    const Ctor = (globalThis as { WebSocket?: new (url: string, protocols: string[]) => WebSocketLike }).WebSocket;
    return Ctor ? (url, protocols) => new Ctor(url, protocols) : undefined;
  }

  /** @internal */
  async headers(): Promise<Record<string, string>> {
    const provided = this.options.headers;
    const source = typeof provided === "function" ? await provided() : provided ?? {};
    const out: Record<string, string> = {};
    for (const [name, value] of Object.entries(source)) out[name.toLowerCase()] = value;
    return out;
  }

  /** A query or a mutation (batched with the other calls of this microtask). */
  unary<A, E>(tag: string, v: number, kind: UnaryKind, input: unknown, options: CallOptions = {}): Promise<RpcResult<A, E>> {
    checkTag(tag);
    return this.unaryCalls.call(tag, v, kind, input, options) as Promise<RpcResult<A, E>>;
  }

  /** A stream call on the frame connection, connecting first; `fallback` takes over when no
   * frame transport has ever connected. `call` resolves to the frame call (`undefined` on the
   * fallback) and rejects when the call could not start. */
  private frameStream(kind: StreamKind, tag: string, v: number, input: unknown, options: SubscribeOptions, fallback?: () => StreamHandle): PendingStream & { call: Promise<FrameCall | undefined> } {
    checkTag(tag);
    let current: StreamHandle | undefined;
    let early: unknown;
    const signal = options.signal;
    signal?.addEventListener("abort", () => {
      if (!current && early === undefined) early = abortReason(signal);
    }, { once: true });
    if (signal?.aborted) early = abortReason(signal);
    const call = this.frames.ensure().then(
      () => {
        if (early !== undefined) throw early;
        const started = this.frames.start(kind, tag, v, input, options);
        current = started.handle;
        return started;
      },
      (error) => {
        if (early !== undefined) throw early;
        if (!fallback || this.frames.transport !== undefined) throw error;
        this.sseFallback = true;
        current = fallback();
        return undefined;
      },
    );
    const handle = call.then(() => current as StreamHandle);
    handle.catch(() => {});
    return {
      call,
      handle,
      current: () => current,
      cancel: () => {
        if (current) current.cancelCall();
        else if (early === undefined) early = cancelledError();
      },
    };
  }

  private stream<O, E>(kind: "server_stream" | "subscription", tag: string, v: number, input: unknown, options: SubscribeOptions): RpcStream<O, E> {
    const sse = () => sseStream(this, kind, tag, v, input, options);
    if (this.sseFallback) {
      checkTag(tag);
      const handle = sse();
      return streamView({ handle: Promise.resolve(handle), current: () => handle, cancel: () => handle.cancelCall() }, options.cursor);
    }
    const allowed = this.options.transports === undefined || this.options.transports.includes("sse");
    return streamView(this.frameStream(kind, tag, v, input, options, allowed ? sse : undefined), options.cursor);
  }

  /** A server stream. */
  serverStream<O, E>(tag: string, v: number, input: unknown, options: CallOptions = {}): RpcStream<O, E> {
    return this.stream("server_stream", tag, v, input, options);
  }

  /** A subscription (resumable: pass a previous stream's `cursor` as `options.cursor`). */
  subscription<O, E>(tag: string, v: number, input: unknown, options: SubscribeOptions = {}): RpcStream<O, E> {
    return this.stream("subscription", tag, v, input, options);
  }

  /** A client stream: sends `items` (waiting for credits), then waits for the result. */
  async clientStream<I, O, E>(tag: string, v: number, items: Iterable<I> | AsyncIterable<I>, options: CallOptions = {}): Promise<RpcResult<O, E>> {
    const pending = this.frameStream("client_stream", tag, v, null, options);
    const call = await pending.call;
    if (!call) throw new RpcTransportError("client streams need WebSocket or WebTransport");
    try {
      for await (const item of items) await this.frames.sendItem(call, item);
      await this.frames.endInput(call);
    } catch (error) {
      if (!call.handle.exit.done) {
        this.frames.cancel(call.id);
        throw error;
      }
    }
    return (await call.handle.exit.promise) as RpcResult<O, E>;
  }

  /** A two-way stream. */
  bidi<I, O, E>(tag: string, v: number, options: CallOptions = {}): RpcDuplex<I, O, E> {
    const pending = this.frameStream("bidi", tag, v, null, options);
    const started = pending.call.then((call) => {
      if (!call) throw new RpcTransportError("two-way streams need WebSocket or WebTransport");
      return call;
    });
    started.catch(() => {});
    return streamView<I, O, E>(pending, undefined, {
      send: async (item: I) => this.frames.sendItem(await started, item),
      end: () => {
        started.then((call) => this.frames.endInput(call)).catch(() => {});
      },
    });
  }

  /** Close the frame connection and fail its open calls. */
  close(): void {
    this.frames.close();
  }
}

function checkTag(tag: string): void {
  if (!TAG.test(tag)) throw new RangeError(`not a procedure tag: ${tag}`);
}